/**
 * Per-kernel eligibility predicates. Each returns true iff the WASM
 * kernel covers the given config; otherwise the dispatcher falls back
 * to tnaj's pure-TS implementation.
 *
 * Constraints mirror `tnaw/STATUS.md` — keep in sync.
 */
import type {
  BootstrapOptions,
  CentralityMeasure,
  StabilityOptions,
  TNA,
} from '../index.js';
import { isGroupTNA } from '../core/index.js';

const CENTRALITIES_WASM: ReadonlySet<string> = new Set([
  'OutStrength', 'InStrength', 'Betweenness',
  'PageRank', 'Diffusion',
  'ClosenessIn', 'ClosenessOut', 'Closeness',
  'Clustering', 'BetweennessRSP',
]);

const ESTIMATE_CS_WASM: ReadonlySet<string> = new Set([
  'OutStrength', 'InStrength', 'Betweenness',
]);

const BOOTSTRAP_SCALING_WASM: ReadonlySet<string> = new Set(['max', 'rank', 'minmax']);

export function canRouteBootstrap(model: TNA, _options: BootstrapOptions = {}): boolean {
  if (isGroupTNA(model)) return false;
  if (!model.data) return false;
  const scaling = (model.scaling as readonly string[] | undefined) ?? [];
  for (const s of scaling) {
    if (!BOOTSTRAP_SCALING_WASM.has(s)) return false;
  }
  return true;
}

export function canRouteCentralities(
  model: TNA,
  options: { measures?: CentralityMeasure[] } = {},
): boolean {
  if (isGroupTNA(model)) return false;
  const requested = options.measures ?? (['OutStrength', 'InStrength', 'Betweenness'] as CentralityMeasure[]);
  for (const m of requested) {
    if (!CENTRALITIES_WASM.has(m as string)) return false;
  }
  return true;
}

export function canRoutePermutation(x: TNA, y: TNA): boolean {
  if (isGroupTNA(x) || isGroupTNA(y)) return false;
  if (!x.data || !y.data) return false;
  if (x.labels.length !== y.labels.length) return false;
  return true;
}

export function canRouteEstimateCS(model: TNA, options: StabilityOptions = {}): boolean {
  if (isGroupTNA(model)) return false;
  if (!model.data) return false;
  const measures = (options.measures ?? ['InStrength', 'OutStrength', 'Betweenness']) as readonly string[];
  for (const m of measures) {
    if (!ESTIMATE_CS_WASM.has(m)) return false;
  }
  return true;
}

export function canRouteCompareWeightMatrices(a: TNA, b: TNA): boolean {
  return a.labels.length === b.labels.length && a.labels.length > 0;
}

export function canRouteMarkovOrderTest(_data: unknown): boolean {
  return true;
}

export function canRoutePassageTime(_x: unknown): boolean {
  return true;
}

export function canRouteMarkovStability(_x: unknown): boolean {
  return true;
}

export function canRouteCasedropReliability(model: TNA): boolean {
  if (isGroupTNA(model)) return false;
  if (!model.data) return false;
  return true;
}

export function canRouteReliabilityAnalysis(
  _sequenceData: unknown,
  modelType: 'tna' | 'ftna' | 'ctna' | 'atna',
): boolean {
  return modelType === 'tna' || modelType === 'ftna';
}

// Clustering is a full port — the Rust kernel covers every dissimilarity
// (hamming/lv/osa/dl/lcs/qgram/cosine/jaccard/jw), every linkage
// (pam + 8 hierarchical methods), and both the string and numeric input
// paths. There is no config tnaj handles that the kernel doesn't, so the
// guards are unconditional. They exist for symmetry with the other
// dispatchers and as a single seam if a future tnaj-only metric appears.
export function canRouteClusterData(_data: unknown): boolean {
  return true;
}

export function canRouteComputeDendrogram(_dist: unknown): boolean {
  return true;
}

export function canRouteFindRepresentatives(_data: unknown): boolean {
  return true;
}

// MMM is the same single-start deterministic EM on both sides (the Rust
// kernel mirrors `tnaj/src/analysis/mmm.ts` line-for-line; both port
// `Nestimate:::.mmm_em`). There is no config tnaj handles that the kernel
// doesn't, so routing is unconditional — the WASM path is just the faster
// one. Equivalence is the MMM contract's ≤1e-6 (loglik) / ARI=1, not
// 1e-10, because EM summation order differs across the boundary.
export function canRouteMmm(_data: unknown): boolean {
  return true;
}
