/**
 * Soft WASM-init for `tnajw/full` (Node target). Wraps tnaw's hard
 * `initTnaw` in a try/catch so a failed WASM load doesn't throw —
 * dispatchers just fall back to tnaj's pure-TS impl instead.
 */
import { initTnaw, isTnawReady } from '../wasm/index.js';

let _initPromise: Promise<boolean> | null = null;

export async function initWasm(): Promise<boolean> {
  if (isTnawReady()) return true;
  if (_initPromise) return _initPromise;
  _initPromise = (async () => {
    try {
      await initTnaw();
      return isTnawReady();
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn('[tnajw/full] WASM init failed; dispatchers will use TS fallback:', err);
      return false;
    }
  })();
  return _initPromise;
}

export function isWasmEnabled(): boolean {
  return isTnawReady();
}
