export function reliabilityAnalysis(
  sequenceData: SequenceData,
  modelType: 'tna' | 'ftna' | 'ctna' | 'atna',
  opts: {
    iter?: number;
    split?: number;
    atnaBeta?: number;
    seed?: number;
    scaling?: string;
    addStartState?: boolean;
    startStateLabel?: string;
    addEndState?: boolean;
    endStateLabel?: string;
  } = {},
): ReliabilityResult {
  if (isWasmEnabled() && canRouteReliabilityAnalysis(sequenceData, modelType)) {
    return wasmReliabilityAnalysis(sequenceData, modelType, opts);
  }
  return tsReliabilityAnalysis(sequenceData, modelType, opts as Parameters<typeof tsReliabilityAnalysis>[2]);
}

// ── Clustering family ─────────────────────────────────────────────
// Signatures are derived from the tnaj implementations via `Parameters<>`
// so the merged surface stays byte-identical to tnaj's public API even
// if tnaj's option bag evolves.

export function clusterData(
  data: Parameters<typeof tsClusterData>[0],
  k: number,
  options?: Parameters<typeof tsClusterData>[2],
): ClusterResult {
  if (isWasmEnabled() && canRouteClusterData(data)) {
    return wasmClusterData(data as Parameters<typeof wasmClusterData>[0], k, options);
  }
  return tsClusterData(data, k, options);
}

export function clusterSequences(
  data: Parameters<typeof tsClusterSequences>[0],
  k: number,
  options?: Parameters<typeof tsClusterSequences>[2],
): ClusterResult {
  if (isWasmEnabled() && canRouteClusterData(data)) {
    return wasmClusterSequences(
      data as Parameters<typeof wasmClusterSequences>[0],
      k,
      options as Parameters<typeof wasmClusterSequences>[2],
    );
  }
  return tsClusterSequences(data, k, options);
}

export function computeDendrogram(
  dist: Matrix,
  method = 'average',
): { merge: number[][]; heights: number[]; order: number[] } {
  if (isWasmEnabled() && canRouteComputeDendrogram(dist)) {
    return wasmComputeDendrogram(dist, method);
  }
  return tsComputeDendrogram(dist, method);
}

export function findRepresentatives(
  data: Parameters<typeof tsFindRepresentatives>[0],
  options?: Parameters<typeof tsFindRepresentatives>[1],
): RepresentativeResult[] {
  if (isWasmEnabled() && canRouteFindRepresentatives(data)) {
    return wasmFindRepresentatives(data, options);
  }
  return tsFindRepresentatives(data, options);
}

// MMM — WASM-accelerated when the engine is up, transparent tnaj-TS
// fallback otherwise. Same contract on both sides (ARI=1 + loglik≤1e-6).
export function mmm(data: MmmInput, options: MmmOptions): MMMResult {
  if (isWasmEnabled() && canRouteMmm(data)) {
    return wasmMmm(data, options);
  }
  return tsMmm(data, options);
}
